PRESS = {
"broadsheet_melb": "Hi Broadsheet team, I'm Yabi, the fragrance specialist behind Khrisha Perfumery. We're opening a niche perfume boutique on Chapel Street, South Yarra, and hosting a VIP launch night with perfumes and curated cocktails.\n\nI've been reading Broadsheet for years, and a lot of where I eat and shop in this city came from your pages. We'd love one of your team to join us. I'm a young founder starting out, and it would mean a lot.\n\n" + DETAILS + "\n\nHappy to share more on the shop if helpful.\nYabi",
"urbanlistmelb": "Hi Urban List team, I'm Yabi, the fragrance specialist behind Khrisha Perfumery. We're opening a niche perfume boutique on Chapel Street, South Yarra, and hosting a VIP launch night with perfumes and curated cocktails.\n\nYou've been my guide to new openings in Melbourne for a long time, so it feels a bit surreal to be writing to you about ours. We'd love someone from your team there. I'm a young founder starting out, and it would mean a lot.\n\n" + DETAILS + "\n\nHappy to send through more details.\nYabi",
"concreteplaygroundmelbourne": "Hi Concrete Playground team, I'm Yabi, the fragrance specialist behind Khrisha Perfumery. We're opening a niche perfume boutique on Chapel Street, South Yarra, and hosting a VIP launch night with perfumes and curated cocktails.\n\nYour culture guide has inspired a lot of my weekends in Melbourne, and we'd love one of your team to come along. I'm a young founder starting out, and it would mean a lot.\n\n" + DETAILS + "\n\nHappy to share more if helpful.\nYabi",
"chapelstprecinct": "Hi Chapel Street Precinct team, I'm Yabi, the fragrance specialist behind Khrisha Perfumery. We're opening a niche perfume boutique on Chapel Street, South Yarra, and hosting a VIP launch night with perfumes and curated cocktails.\n\nChapel Street has always been the street I looked up to in Melbourne, and we really want to be part of it, not just on it. We'd love you to come and meet us. I'm a young founder starting out, and it would mean a lot.\n\n" + DETAILS + "\n\nHope to see you there.\nYabi",
}

def build():
    out = {}
    for k, (n, p, sign) in P.items():
        out[k] = OPEN.format(n=n) + "\n\n" + p + " " + CLOSE_LINE + "\n\n" + DETAILS + "\n\n" + sign + ",\nYabi"
    out.update(PRESS)
    return out
